<?php
$eligible=safeRun($pdo,"SELECT fr.id final_result_id,fr.final_score,fr.grade,fr.released_at,u.full_name,s.matric_number FROM final_results fr JOIN students s ON s.id=fr.student_id JOIN users u ON u.id=s.user_id LEFT JOIN certificates c ON c.final_result_id=fr.id WHERE fr.semester_id=? AND fr.status='released' AND fr.grade IN ('A','B','C') AND c.id IS NULL ORDER BY u.full_name",[$currentSemesterId])->fetchAll();
$certs=safeRun($pdo,"SELECT c.*,u.full_name,s.matric_number,fr.final_score FROM certificates c JOIN users u ON u.id=c.user_id LEFT JOIN students s ON s.user_id=u.id LEFT JOIN final_results fr ON fr.id=c.final_result_id WHERE u.role='student' ORDER BY c.issued_at DESC")->fetchAll();
?>
<div class="card-fy mb-3"><div class="section-title">Issue Completion Certificate</div><p class="small text-muted">Only students with a released passing final result can receive a certificate. The grade is taken from the finalized result and cannot be entered manually.</p><form method="post" class="row g-3 align-items-end"><?= csrfField() ?><input type="hidden" name="action" value="generate_certificate"><div class="col-md-9"><label class="form-label small fw-semibold">Eligible released result</label><select required name="final_result_id" class="form-control-fy w-100"><option value="">Select student</option><?php foreach($eligible as $r): ?><option value="<?= $r['final_result_id'] ?>"><?= e($r['full_name']) ?> (<?= e($r['matric_number']) ?>) — <?= e($r['final_score']) ?>/100, Grade <?= e($r['grade']) ?></option><?php endforeach; ?></select></div><div class="col-md-3"><button class="btn-fy-orange w-100" <?= !$eligible?'disabled':'' ?>>Issue certificate</button></div></form><?php if(!$eligible): ?><div class="small text-muted mt-3">No unrewarded eligible results are available.</div><?php endif; ?></div>
<div class="card-fy"><div class="section-title">Issued Student Certificates</div><div class="table-responsive"><table class="table-fy"><thead><tr><th>Code</th><th>Student</th><th>Result</th><th>Issued</th><th></th></tr></thead><tbody><?php foreach($certs as $c): ?><tr><td><code><?= e($c['cert_code']) ?></code></td><td><?= e($c['full_name']) ?><div class="small text-muted"><?= e($c['matric_number']) ?></div></td><td><?= e($c['final_score']??'—') ?>/100 · Grade <?= e($c['grade']??'—') ?></td><td><?= e(date('M j, Y',strtotime($c['issued_at']))) ?></td><td><a target="_blank" class="btn-fy-outline btn-sm" href="<?= BASE_URL ?>/dashboard/certificate_download.php?type=certificate&id=<?= $c['id'] ?>">View PDF</a></td></tr><?php endforeach; ?><?php if(!$certs): ?><tr><td colspan="5" class="text-center text-muted py-4">No student certificates issued.</td></tr><?php endif; ?></tbody></table></div></div>
